mapper.select:
SELECT o.*, o.order_id AS id FROM ct_gm.t_od_order o WHERE o.is_del = 0 AND o.review_result = 1 AND o.is_producible = 1 AND o.status = 11 AND o.close_time IS NULL AND NOT EXISTS ( SELECT 1 FROM ct_gm.t_pl_prod_plan p WHERE p.order_id = o.order_id AND p.is_del = 0 )
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.contract_no LIKE CONCAT('%', #{keyword}, '%') OR o.unit_id IN ( SELECT u.unit_id FROM ct_gm.t_sys_unit u WHERE u.unit_name LIKE CONCAT('%', #{keyword}, '%') AND u.is_del = 0 ) )
AND o.unit_id = #{unitId}
AND o.order_date >= #{orderDateStart}
AND o.order_date <= #{orderDateEnd}
AND o.delivery_date_plan >= #{deliveryDateStart}
AND o.delivery_date_plan <= #{deliveryDateEnd}
ORDER BY o.created_at DESC

SELECT COUNT(*) FROM ct_gm.t_pl_prod_plan
WHERE prod_plan_no=#{prodPlanNo} AND is_del=0
AND prod_plan_id != #{excludeId}

SELECT COUNT(*) FROM ct_gm.t_pl_prod_plan
WHERE order_id=#{orderId} AND is_del=0
AND prod_plan_id != #{excludeId}
